def word_break(s: str, words: list) -> bool:
    word_set = set(words)
    lengths = {len(w) for w in word_set}
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n + 1):
        for length in lengths:
            if i >= length and dp[i - length] and s[i - length:i] in word_set:
                dp[i] = True
                break

    return dp[n]
```

